# "Does the list contain a duplicate?" at three complexities.

def has_dup_pairs(a: list[int]) -> bool:
    # O(n^2) time, O(1) extra space: compare every pair
    for i in range(len(a)):
        for j in range(i + 1, len(a)):
            if a[i] == a[j]:
                return True
    return False

def has_dup_sort(a: list[int]) -> bool:
    # O(n log n) time, O(n) space for the sorted copy: duplicates become neighbors
    b = sorted(a)
    return any(b[i] == b[i + 1] for i in range(len(b) - 1))

def has_dup_set(a: list[int]) -> bool:
    # O(n) average time, O(n) space: trade memory for one pass
    seen = set()
    for x in a:
        if x in seen:      # O(1) average on a set; O(n) on a list
            return True
        seen.add(x)
    return False
